from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
import json
from pathlib import Path
from threading import Lock

from .gemini import (
    PROMPT_VERSION,
    DailyQuotaExhausted,
    GeminiClient,
    cache_key,
    generation_config,
)
from .io import read_jsonl, sha256_text, write_json, write_jsonl
from .scoring import extract_answer, score_answer


MODES = ("no_visual", "native_vision", "lens_compact", "lens_balanced", "lens_detailed")
MODEL_CLASSES = {
    "gemini-2.5-pro": "high-capability",
    "gemini-2.5-flash": "balanced",
    "gemini-2.5-flash-lite": "lightweight",
}


def discover_models(client: GeminiClient, artifact_root: Path) -> dict:
    response = client.list_models()
    rows = [
        item
        for item in response.get("models", [])
        if "generateContent" in item.get("supportedGenerationMethods", [])
    ]
    available = {item["name"].removeprefix("models/") for item in rows}
    selected = [model for model in MODEL_CLASSES if model in available]
    result = {
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "api_version": "v1beta",
        "generate_content_models": rows,
        "selected_models": [
            {"model_id": model, "capability_class": MODEL_CLASSES[model]} for model in selected
        ],
        "selection_policy": "stable exact IDs spanning high-capability, balanced and lightweight classes",
        "true_image_incapable_model": None,
        "true_image_incapable_model_note": "No general-purpose accessible model was verified as image-incapable; a Gemma candidate accepted an image probe.",
    }
    write_json(artifact_root / "model-discovery.json", result)
    return result


def _task_rows(
    artifact_root: Path,
    model_ids: list[str],
    image_ids: set[str] | None,
    repeat_index: int,
) -> list[dict]:
    manifest = json.loads((artifact_root / "dataset-manifest.json").read_text(encoding="utf-8"))
    images = {item["image_id"]: item for item in manifest["images"]}
    questions = read_jsonl(artifact_root / "questions.jsonl")
    truth = {item["question_id"]: item for item in read_jsonl(artifact_root / "ground-truth.jsonl")}
    descriptions = {
        item["image_id"]: item for item in read_jsonl(artifact_root / "lens-descriptions.jsonl")
    }
    tasks = []
    for question in questions:
        image_id = question["image_id"]
        if image_ids is not None and image_id not in image_ids:
            continue
        image = images[image_id]
        description = descriptions[image_id]
        for model_id in model_ids:
            for mode in MODES:
                detail = mode.removeprefix("lens_") if mode.startswith("lens_") else None
                tasks.append(
                    {
                        "benchmark_version": manifest["benchmark_version"],
                        "model_id": model_id,
                        "capability_class": MODEL_CLASSES[model_id],
                        "question": question,
                        "ground_truth": truth[question["question_id"]],
                        "image": image,
                        "mode": mode,
                        "lens_mode": detail,
                        "lens_text": description[detail] if detail else None,
                        "lens_description_sha256": (
                            description["description_sha256"][detail] if detail else None
                        ),
                        "repeat_index": repeat_index,
                    }
                )
    return tasks


def _execute(client: GeminiClient, task: dict) -> dict:
    question = task["question"]
    truth = task["ground_truth"]
    image = task["image"]
    result = client.generate(
        model_id=task["model_id"],
        image_sha256=image["sha256"],
        question_id=question["question_id"],
        question=question["question"],
        mode=task["mode"],
        image_path=Path(image["local_path"]) if task["mode"] == "native_vision" else None,
        lens_text=task["lens_text"],
        lens_description_sha256=task["lens_description_sha256"],
        repeat_index=task["repeat_index"],
    )
    answer = extract_answer(result.raw_model_answer) if result.status == "ok" else None
    normalized, correct = score_answer(answer, truth["accepted_answers"], question["category"])
    request_identity = {
        "model_id": task["model_id"],
        "image_sha256": image["sha256"],
        "question_id": question["question_id"],
        "mode": task["mode"],
        "lens_description_sha256": task["lens_description_sha256"],
        "prompt_version": PROMPT_VERSION,
        "generation_config": generation_config(task["model_id"]),
        "repeat_index": task["repeat_index"],
    }
    return {
        "benchmark_version": task["benchmark_version"],
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "request_id": sha256_text(
            json.dumps(request_identity, sort_keys=True, separators=(",", ":"))
        ),
        "image_id": question["image_id"],
        "image_sha256": image["sha256"],
        "question_id": question["question_id"],
        "question": question["question"],
        "category": question["category"],
        "model_id": task["model_id"],
        "capability_class": task["capability_class"],
        "mode": task["mode"],
        "lens_mode": task["lens_mode"],
        "lens_text": task["lens_text"],
        "lens_description_sha256": task["lens_description_sha256"],
        "ground_truth": truth["primary_answer"],
        "accepted_answers": truth["accepted_answers"],
        "raw_model_answer": result.raw_model_answer,
        "parsed_answer": answer,
        "normalized_answer": normalized,
        "correct": correct if result.status == "ok" else None,
        "status": result.status,
        "latency_ms": result.latency_ms,
        "usage": result.usage,
        "attempts": result.attempts,
        "retries": result.retries,
        "error": result.error,
        "cache_hit": result.cache_hit,
        "repeat_index": task["repeat_index"],
        "prompt_version": PROMPT_VERSION,
        "generation_config": generation_config(task["model_id"]),
        "raw_response": result.raw_response,
    }


def run_tasks(
    client: GeminiClient,
    artifact_root: Path,
    model_ids: list[str],
    *,
    image_ids: set[str] | None = None,
    repeat_index: int = 0,
    workers: int = 8,
    output_path: Path | None = None,
) -> list[dict]:
    tasks = _task_rows(artifact_root, model_ids, image_ids, repeat_index)
    results = []
    progress_lock = Lock()
    processed = 0
    exhausted_models = set()
    with ThreadPoolExecutor(max_workers=workers) as executor:
        futures = [executor.submit(_execute, client, task) for task in tasks]
        for future in as_completed(futures):
            try:
                results.append(future.result())
            except DailyQuotaExhausted as exc:
                exhausted_models.add(exc.model_id)
            with progress_lock:
                processed += 1
                if processed % 100 == 0 or processed == len(tasks):
                    print(
                        json.dumps(
                            {
                                "processed": processed,
                                "total": len(tasks),
                                "successful_results": len(results),
                                "failures": sum(item["status"] != "ok" for item in results),
                                "retries": sum(item["retries"] for item in results),
                                "daily_quota_exhausted_models": sorted(exhausted_models),
                            }
                        ),
                        flush=True,
                    )
    results.sort(
        key=lambda item: (
            item["repeat_index"],
            item["model_id"],
            item["image_id"],
            item["question_id"],
            item["mode"],
        )
    )
    if output_path is not None:
        write_jsonl(output_path, results)
    return results


def harvest_cached_tasks(
    cache_root: Path,
    artifact_root: Path,
    model_ids: list[str],
    *,
    image_ids: set[str] | None = None,
    repeat_index: int = 0,
) -> tuple[list[dict], list[dict]]:
    client = GeminiClient("cache-only", cache_root)
    tasks = _task_rows(artifact_root, model_ids, image_ids, repeat_index)
    cached_tasks = []
    for task in tasks:
        path = cache_root / (
            cache_key(
                task["model_id"],
                task["image"]["sha256"],
                task["question"]["question_id"],
                task["mode"],
                task["lens_description_sha256"],
                task["repeat_index"],
            )
            + ".json"
        )
        if not path.is_file():
            continue
        value = json.loads(path.read_text(encoding="utf-8"))
        if value.get("status") == "ok":
            cached_tasks.append(task)
    rows = [_execute(client, task) for task in cached_tasks]
    by_question: dict[str, list[dict]] = {}
    for row in rows:
        by_question.setdefault(row["question_id"], []).append(row)
    expected = {(model_id, mode) for model_id in model_ids for mode in MODES}
    complete_question_ids = {
        question_id
        for question_id, members in by_question.items()
        if {(row["model_id"], row["mode"]) for row in members} == expected
    }
    complete = [row for row in rows if row["question_id"] in complete_question_ids]

    def key(item: dict) -> tuple:
        return (
            item["model_id"],
            item["image_id"],
            item["question_id"],
            item["mode"],
        )
    rows.sort(key=key)
    complete.sort(key=key)
    return rows, complete
